mapper.select:
SELECT CASE WHEN COUNT(*) > 0 AND MAX(is_available) = 1 THEN true ELSE false END
FROM student_schedule
WHERE student_id = #{studentId} AND day_of_week = #{dayOfWeek} AND time_slot = #{timeSlot}

SELECT * FROM student_schedule
WHERE student_id = #{studentId} AND day_of_week = #{dayOfWeek} AND time_slot = #{timeSlot}
LIMIT 1

SELECT DISTINCT student_id
FROM student_schedule
WHERE day_of_week = #{dayOfWeek}
  AND time_slot = #{timeSlot}
  AND is_available = 1
